'use client';
import { useState, useRef, useEffect } from 'react';
import ReactMarkdown from 'react-markdown';
import { useParams, useRouter } from 'next/navigation';

interface Mensaje {
  role: 'estudiante' | 'profesor';
  texto: string;
}

export default function AulaChat() {
  const params = useParams();
  const router = useRouter();
  const student = params.student as string;
  
  const [mensajes, setMensajes] = useState<Mensaje[]>([]);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isMounted, setIsMounted] = useState(false);

  // Configuración según el perfil
  const config = student === 'avril' 
    ? { nombre: "Avril", nivel: "8vo de Básica", asignatura: "Investigación y Ciencias" }
    : { nombre: "Gael", nivel: "4to de Básica", asignatura: "Exploración y Retos" };

  useEffect(() => {
    setIsMounted(true);
    const saved = localStorage.getItem(`chatHistory_${student}`);
    if (saved) setMensajes(JSON.parse(saved));
  }, [student]);

  useEffect(() => {
    if (isMounted) localStorage.setItem(`chatHistory_${student}`, JSON.stringify(mensajes));
  }, [mensajes, isMounted, student]);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [mensajes, loading]);

  const enviarMensaje = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim()) return;

    const nuevoMensaje: Mensaje = { role: 'estudiante', texto: input };
    const historialActualizado = [...mensajes, nuevoMensaje];
    
    setMensajes(historialActualizado);
    setInput('');
    setLoading(true);

    try {
      const res = await fetch('/api/profesor', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          preguntaEstudiante: input,
          asignatura: config.asignatura,
          nivelEducativo: config.nivel,
          historialConversacion: mensajes,
        }),
      });

      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      setMensajes([...historialActualizado, { role: 'profesor', texto: data.respuesta }]);
    } catch (error: any) {
      setMensajes([...historialActualizado, { role: 'profesor', texto: error.message }]);
    } finally {
      setLoading(false);
    }
  };

  if (!isMounted) return null;

  return (
    <div className="flex flex-col min-h-screen bg-gray-50">
      <header className="bg-blue-600 text-white p-4 shadow-md sticky top-0 z-10 flex justify-between items-center">
        <button onClick={() => router.push('/')} className="text-sm font-semibold hover:underline">← Volver</button>
        <div className="text-center">
          <h1 className="text-xl font-bold">Profesor de {config.nombre}</h1>
          <p className="text-xs opacity-90">{config.asignatura}</p>
        </div>
        <div />
      </header>

      <main ref={scrollRef} className="flex-1 overflow-y-auto p-4 space-y-4 mb-20 scroll-smooth">
        {mensajes.map((msg, i) => (
          <div key={i} className={`flex ${msg.role === 'estudiante' ? 'justify-end' : 'justify-start'}`}>
            <div className={`max-w-[80%] p-3 rounded-lg ${
              msg.role === 'estudiante' 
                ? 'bg-blue-500 text-white rounded-br-none' 
                : 'bg-white border text-gray-800 rounded-bl-none shadow-sm prose prose-sm'
            }`}>
              {msg.role === 'profesor' ? <ReactMarkdown>{msg.texto}</ReactMarkdown> : msg.texto}
            </div>
          </div>
        ))}
        {loading && <div className="p-3 bg-gray-200 rounded animate-pulse">Escribiendo...</div>}
      </main>

      <form onSubmit={enviarMensaje} className="fixed bottom-0 w-full p-4 bg-white border-t flex gap-2">
        <input value={input} onChange={(e) => setInput(e.target.value)} className="flex-1 border p-2 rounded" placeholder="Escribe tu duda..." />
        <button disabled={loading} className="bg-blue-600 text-white px-6 py-2 rounded">Enviar</button>
      </form>
    </div>
  );
}
